body {
  font-family: system-ui, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 1.125rem;
  line-height: 1.5rem;
  color: #ffffff;
  margin: 0px;
}

p {
  line-height: 1.9rem;
}

h1, h2, h3, h4, h5, h6 {
  line-height: normal;
  margin: 0;
  padding: 0;
}

a {
  text-decoration: none;
  color: #ffffff;
}
a:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}

a.active,
a:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border: 1px solid currentColor;
  border-radius: 4px;
  font: inherit;
  color: inherit;
  background: transparent;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
}

a.btn {
  color: inherit;
  text-decoration: none;
}

.btn:hover,
a.btn:hover {
  text-decoration: none;
}

.btn:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

ul.list-none {
  list-style-type: none;
}

main a {
  color: #ffffff;
  text-decoration: underline;
  text-underline-offset: 4px;
}
main a:hover {
  color: #4f9eea;
  text-underline-offset: 4px;
}
main a.clr-underline {
  color: #4f9eea;
}
