body {
  font-family: system-ui, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 1.125rem;
  line-height: 1.5rem;
  color: #ffffff;
  margin: 0px;
}

p {
  line-height: 1.9rem;
}

h1, h2, h3, h4, h5, h6 {
  line-height: normal;
  margin: 0;
  padding: 0;
}

a {
  text-decoration: none;
  color: #ffffff;
}
a:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}

a.active,
a:hover {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border: 1px solid currentColor;
  border-radius: 4px;
  font: inherit;
  color: inherit;
  background: transparent;
  text-align: center;
  text-decoration: none;
  vertical-align: middle;
  cursor: pointer;
}

a.btn {
  color: inherit;
  text-decoration: none;
}

.btn:hover,
a.btn:hover {
  text-decoration: none;
}

.btn:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

ul.list-none {
  list-style-type: none;
}

main a {
  color: #ffffff;
  text-decoration: underline;
  text-underline-offset: 4px;
}
main a:hover {
  color: #00d886;
  text-underline-offset: 4px;
}
main a.clr-underline {
  color: #00d886;
}
main a.clr-underline:hover {
  color: #00e78f;
}

article.post {
  /* Default list items */
  /* List items that contain <p> (Markdown block items) */
}
article.post h1 {
  font-size: var(--fs-40);
  line-height: var(--lh-40);
}
article.post h2 {
  font-size: var(--fs-32);
  line-height: var(--lh-32);
}
article.post h3 {
  font-size: var(--fs-28);
  line-height: var(--lh-28);
}
article.post h4 {
  font-size: var(--fs-24);
  line-height: var(--lh-24);
}
article.post h5 {
  font-size: var(--fs-20);
  line-height: var(--lh-20);
}
article.post h6 {
  font-size: var(--fs-16);
  line-height: var(--lh-16);
}
article.post h2 {
  margin: 64px 0 24px;
}
article.post h3 {
  margin: 40px 0 24px;
}
article.post p {
  line-height: 24px;
  margin-bottom: 24px;
  overflow-wrap: break-word;
}
article.post ul {
  padding-left: 3rem;
  list-style-type: circle;
  line-height: 2rem;
  margin-bottom: 24px;
}
article.post li {
  margin-bottom: 0.75rem;
}
article.post li p {
  margin-bottom: 0.75rem;
}

hr {
  border: 0;
  border-top: 1px dotted #efefef;
}

pre {
  background: #412677;
  padding: 1.5em 14px;
  margin-bottom: 2rem;
  overflow-x: auto;
  border-radius: 1rem;
}

code:not(pre code) {
  background: #412677;
  padding: 2px 8px;
  font-size: 1.2rem;
  color: #c6c9e5;
  overflow: auto;
  border-radius: 4px;
}

pre code {
  padding: 0px;
}

.position-relative {
